CREATE TABLE IF NOT EXISTS apps(id TEXT PRIMARY KEY, name TEXT NOT NULL, icon TEXT NOT NULL, category TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage(day TEXT, hour INTEGER, app TEXT, site TEXT, ms INTEGER NOT NULL, PRIMARY KEY(day,hour,app,site)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS rules(kind TEXT, id TEXT, category TEXT NOT NULL, PRIMARY KEY(kind,id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS settings(id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS names(id INTEGER PRIMARY KEY, value TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS buckets(day TEXT, hour INTEGER, app INTEGER, site INTEGER, ms INTEGER NOT NULL, PRIMARY KEY(day,hour,app,site)) WITHOUT ROWID;
CREATE VIEW IF NOT EXISTS all_usage AS SELECT day,hour,app,site,ms FROM usage UNION ALL SELECT b.day,b.hour,a.value,s.value,b.ms FROM buckets b JOIN names a ON a.id=b.app JOIN names s ON s.id=b.site;
